ee:message.ee:set-payload:
%dw 2.0
output application/json

var collection = payload
var envValues = vars.currentEnvironment.values default []
var envMap = envValues reduce (item, acc={}) -> 
    acc ++ {(item.key): item.value}

var collectionVars = collection.variable default []
var collectionVarMap = collectionVars reduce (item, acc={}) -> 
    acc ++ {(item.key): item.value}

// Function to replace variables in a string
fun replaceVariables(str: String): String = do {
    var envKeys = envMap pluck $$
    var colKeys = collectionVarMap pluck $$

    // First pass: Replace with environment variables
    var withEnvReplaced = if (isEmpty(envKeys)) str 
        else envKeys reduce (key, result=str) -> 
            result replace ("\\{\\{" ++ key ++ "\\}\\}") with (envMap[key] as String)
    ---
    // Second pass: Replace with collection variables
    if (isEmpty(colKeys)) withEnvReplaced
        else colKeys reduce (key, result=withEnvReplaced) -> 
            result replace ("\\{\\{" ++ key ++ "\\}\\}") with (collectionVarMap[key] as String)
}

// This function ONLY processes values within REQUEST objects
fun processRequestValue(value): Any = 
    if (value == null) null
    else value match {
        case is String -> replaceVariables(value)
        case is Number -> value
        case is Boolean -> value
        case is Array -> value map processRequestValue($)
        case is Object -> value mapObject ((v, k) -> {
            (k): processRequestValue(v)
        })
        else -> value
    }

// Recursive function to flatten items
fun flattenItems(items: Array): Array = 
    items flatMap (item) -> 
        if (item.request?) 
            [{
                name: item.name,
                // ONLY apply variable replacement to the request object
                request: processRequestValue(item.request)
            }]
        else if (item.item?)
            // Recurse through folders without modifying anything
            flattenItems(item.item)
        else
            []

---
flattenItems(collection.item default [])
